using System;using System.IO;using System.Text;using System.Linq;using Frociart;
public static class FpgtRendererSmokeTests {
 public static int Main(string[] args){try{string root=args[0];var document=FlowPseudocode.Decode("DICHIARA x: INTERO\nx=2\nSTAMPA x+1");var program=FlowSource.Compile(document);byte[] before=DiagramIO.EncodeDocument(document);Directory.CreateDirectory(Path.Combine(root,"render-smoke"));int count=0,failed=0;foreach(string file in Directory.GetFiles(Path.Combine(root,"references/installed"),"*.fpgt").OrderBy(x=>x,StringComparer.Ordinal)){FlowFpgtSyntax model;try{model=FlowFpgtSyntax.Parse(File.ReadAllText(file));}catch(FlowFpgtSyntax.SyntaxError){continue;}try{var code=FlowFpgt.Generate(model,program);if(!before.SequenceEqual(DiagramIO.EncodeDocument(document)))throw new Exception("Document changed");if(code.Text.Length==0)throw new Exception("Empty code");foreach(var scope in program.Scopes)foreach(var node in scope.Blocks)if(code.ForBlock(scope.Id,node.Id).Count==0)throw new Exception("Missing map");File.WriteAllText(Path.Combine(root,"render-smoke",Path.GetFileNameWithoutExtension(file)+"."+model.Extension),code.Text,new UTF8Encoding(false));Console.WriteLine("PASS "+model.Name);count++;}catch(Exception e){Console.WriteLine("FAIL "+Path.GetFileName(file)+" "+e.Message);failed++;}}Console.WriteLine("FPGT_RENDERER_SMOKE "+(failed==0?"PASS":"FAIL")+" models="+count+" failed="+failed);return failed==0?0:1;}catch(Exception e){Console.WriteLine(e);return 1;}}
}
